43	void launchGemm(const float* dA, const float* dB, float* dC, int N) {
44	    dim3 block(TILE, TILE);
45	    dim3 grid(N / TILE, N / TILE);  // one block per output tile
46	    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
47	}

