using frag_a = wmma::fragment<wmma::matrix_a, MMA_M, MMA_N, MMA_K, float, wmma::row_major>;
using frag_b = wmma::fragment<wmma::matrix_b, MMA_M, MMA_N, MMA_K, float, wmma::row_major>;
using frag_c = wmma::fragment<wmma::accumulator, MMA_M, MMA_N, MMA_K, float>;

// Number of warps per tile dimension
#define WARPS_PER_TILE (TILE / MMA_M)  // 4
#define TOTAL_WARPS (WARPS_PER_TILE * WARPS_PER_TILE)  // 16

