using frag_b = wmma::fragment<wmma::matrix_b, MMA_K, MMA_N, MMA_K, float, wmma::row_major>;
using frag_c = wmma::fragment<wmma::accumulator, MMA_M, MMA_N, MMA_K, float>;

__global__ void gemmKernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    extern __shared__ char sMem[];
    float* sA = reinterpret_cast<float*>(sMem);
    float* sB = sA + TILE * TILE;

    const int warpId = threadIdx.x / 32;
    const int warpRow = warpId / WARP_GROUPS;
    const int warpCol = warpId % WARP_GROUPS;
    const int lane = threadIdx.x % 32;

    int gRow = blockIdx.y * TILE + warpRow * MMA_M;
    int gCol = blockIdx.x * TILE + warpCol * MMA_N;

    frag_c accum;
    wmma::fill_fragment(accum, 0.0f);

    int numTiles = (N + TILE - 1) / TILE;
    int kSteps = (N + MMA_K - 1) / MMA_K;

    for (int t = 0; t < numTiles; ++t) {
        // Cooperative load of A tile (64x64) into sA
        for (int i = lane; i < TILE * TILE; i += 32) {
            int row = i / TILE;
            int col = i % TILE;
            int gr = t * TILE + warpRow * MMA_M + row;
            int gc = t * TILE + col;
            if (gr < N && gc < N)
                sA[i] = A[gr * N + gc];
            else
                sA[i] = 0.0f;
        }

        // Cooperative load of B tile (64x64) into sB
        for (int i = lane; i < TILE * TILE; i += 32) {
            int row = i / TILE;
            int col = i % TILE;
            int gr = t * TILE + row;
            int gc = t * TILE + warpCol * MMA_N + col;
            if (gr < N && gc < N)
                sB[i] = B[gr * N + gc];
            else
                sB[i] = 0.0f;
        }

        __syncthreads();

        // For each k-step: load 16x16 sub-tile from A and B, execute wmma
        for (int ks = 0; ks < kSteps; ++ks) {
            frag_a fa;
            frag_b fb;

            int kStart = t * TILE + ks * MMA_K;

            // Load A: 16x16 sub-tile starting at (warpRow*16, kStart)
            wmma::load_matrix_sync(fa, sA + kStart * TILE + warpRow * MMA_M * (TILE + 1), TILE);

            // Load B: 16x16 sub-tile starting at (kStart, warpCol*16)
            wmma::load_matrix_sync(fb, sB + kStart * TILE + warpCol * MMA_N, TILE);

            // Execute wmma
            wmma::mma_sync(accum, fa, fb, accum);
        }

        __syncthreads();
    }

    // Store result
    for (int i = lane; i < MMA_M * MMA_N; i += 32) {
        int row = i / MMA_N;
        int col = i % MMA_N;
        int gr = gRow + row;
        int gc = gCol + col;
        if (gr < N && gc < N)
            C[gr * N + gc] = accum.x[i];
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    int smem = 2 * TILE * TILE * sizeof(float);
    dim3 block(BLOCK_THREADS);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block, smem>>>(dA, dB, dC, N);
}
