#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;

// ============================================================================
// Tensor-core tiled GEMM: C = A * B for NxN row-major FP32 matrices.
// Uses wmma FP16×FP16→FP32 multiply-accumulate.
//
// Tile size: 64×64, processed as 4×4=16 wmma sub-tiles.
// Block: 16 warps (512 threads). Each warp handles one 16×16 sub-tile.
// Shared memory: 2 × 64 × 64 half = 16 KB (for FP16 A and B tiles).
// ============================================================================

#define TILE 64
#define MMA 16
#define WGRP 4  // warp groups per tile dimension (4×4=16 warps total)
#define SBYTES (2 * TILE * TILE * sizeof(half))

using matA = wmma::fragment<wmma::matrix_a, MMA, MMA, MMA, half, wmma::row_major>;
using matB = wmma::fragment<wmma::matrix_b, MMA, MMA, MMA, half, wmma::col_major>;
using accC = wmma::fragment<wmma::accumulator, MMA, MMA, MMA, float>;

__global__ void gemmKernel(const float* __restrict__ dA,
                           const float* __restrict__ dB,
                           float* __restrict__ dC,
                           int N) {
    extern __shared__ char smem[];
    half* __restrict__ sA = reinterpret_cast<half*>(smem);
    half* __restrict__ sB = sA + TILE * TILE;

    const int numTiles = (N + TILE - 1) / TILE;
    const int warpId = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;

    // Warp-group coordinates
    const int wgRow = warpId / WGRP;  // 0..3
    const int wgCol = warpId % WGRP;   // 0..3

    // Output position (top-left of 16×16 sub-tile)
    const int gRow = blockIdx.y * TILE + wgRow * MMA;
    const int gCol = blockIdx.x * TILE + wgCol * MMA;

    // 4 accumulators: one per column position
    accC accum[WGRP];
    #pragma unroll
    for (int j = 0; j < WGRP; ++j)
        wmma::fill_fragment(accum[j], 0.0f);

    // Inner dimension in matrix units: TILE = 64 = 4×MMA
    // For each k-step (w = 0..3):
    //   C += A[gRow:gRow+16][tile+w*MMA:tile+w*MMA+MMA] ×
    //         B[tile+w*MMA:tile+w*MMA+MMA][gCol:gCol+16]
    // There are 4 such k-steps per tile.

    for (int t = 0; t < numTiles; ++t) {
        const int ts = t * TILE;

        // -----------------------------------------------------------
        // 1) Cooperative global-load + convert FP32→FP16 → shared mem
        // -----------------------------------------------------------
        // Thread (warpId, lane) → (row_in_tile, col_in_tile) in the 64×64 tile:
        //   row_in_tile = lane                    (0..31)
        //   col_in_tile = warpId                  (0..15)
        // Each thread loads 8 half values from A and 8 from B (16×8=128 per matrix,
        // but actually we need 64×64=4096 per matrix, 4096/512=8 per thread).
        //
        // Row in global: ts + lane
        // Col in global: ts + warpId
        // Each thread loads 8 consecutive elements: col = ts+warpId .. ts+warpId+7
        // But consecutive in a row → not coalesced (stride = N).
        //
        // Better layout: row = warpId, col = lane.
        //   Row in global: ts + warpId (0..15)
        //   Col in global: ts + lane   (0..31)
        // Each thread loads: A[(ts+warpId)*N + ts+lane + k*32] for k=0,1
        // That gives row-stride access, which is NOT coalesced.
        //
        // Best coalesced load: contiguous warps (same warpId, consecutive lane)
        //   → consecutive elements in global memory → coalesced.
        // Thread (warpId, lane) loads A[(ts+lane)*N + ts+warpId*2 + 0..1]
        // This is: 2 consecutive elements per thread → 2*32*2 = 2048 bytes per warp
        // per load. 2 loads (A and B).
        // Total elements loaded: 512 threads × 2 (rows) × 2 (elements per thread)
        //   = 2048 elements × 2 matrices = 4096 half per matrix = 64×64. ✓

        // Cooperative load of A tile
        // Thread maps: row_in_tile = lane, col_in_tile = warpId
        // Loads 2 elements starting at [lane][warpId*2 + k] in the tile
        // Global: (ts + lane) * N + ts + warpId*2 + k

        const int tileRowA = ts + lane;
        const int tileColA = ts + warpId * 2;
        const int strideA = N;

        if (tileRowA < N) {
            const float* __restrict__ a0 = dA + tileRowA * strideA + tileColA;
            const float* __restrict__ a1 = a0 + 2;
            // Store to shared memory: row-major sA[row*64+col]
            // Thread stores at: lane*64 + warpId*2 + 0, lane*64 + warpId*2 + 1
            // Wait, but we need to be careful about bank conflicts and coalescing.
            // Shared memory is word-addressable (32-bit = 4-byte words).
            // With 32 threads per warp, 64 columns → 2 words per row.
            // Row lane: threads 0-31, columns 0-63. Each thread handles 2 columns.
            // Col 0→thread 0, col 1→thread 0, col 2→thread 1, etc.
            // Thread i loads columns 2i, 2i+1 → word address 2i/2 = i. Coalesced! ✓

            // Actually: sA[row * TILE + col]. The row is lane, and each thread
            // loads 2 consecutive cols = warpId*2 and warpId*2+1.
            // Thread accesses: sA[lane*64 + warpId*2] and sA[lane*64 + warpId*2 + 1]
            // These are 32-bit apart (half = 2 bytes). Not naturally aligned for
            // 32-bit coalescing. But we can still do it.

            sA[lane * TILE + warpId * 2 + 0] = __float2half(a0[0]);
            sA[lane * TILE + warpId * 2 + 1] = __float2half(a0[1]);
            sA[lane * TILE + warpId * 2 + 2] = __float2half(a1[0]);
            sA[lane * TILE + warpId * 2 + 3] = __float2half(a1[1]);
            sA[lane * TILE + warpId * 2 + 4] = __float2half(a0[4]);
            sA[lane * TILE + warpId * 2 + 5] = __float2half(a0[5]);
            sA[lane * TILE + warpId * 2 + 6] = __float2half(a1[4]);
            sA[lane * TILE + warpId * 2 + 7] = __float2half(a1[4]);
        }

        // Hmm, the above is getting messy. Let me simplify:
        // Each thread loads 8 elements from A: 2 rows × 4 elements per row
        // But that's only if we organize by 2 rows per warp group.

        // SIMPLEST CORRECT APPROACH: just load 1 element per thread with proper mapping.
        // We have 512 threads and 64×64×2 = 8192 half values (A and B combined).
        // 8192/512 = 16 half values per thread.
        // So each thread loads 16 half values: 8 from A and 8 from B.

        // Actually, I'll just write the load loops explicitly for clarity.
        // Each thread handles row = lane, and 2 rows per iteration.
        // 32 lanes → 32 rows. Two warp groups (0-15) cover rows 0-31.
        // Each thread loads 2 rows of 32 elements each = 64 half values.
        // But we only need 64×64 = 4096 values, so 4096/512 = 8 per thread.

        // I'll do: each thread loads 2 half from A (row=lane, cols=warpId*2 and warpId*2+1)
        // and 2 half from B, twice (for 4 elements each = 8 total).
        // No wait, 64×64=4096 half per matrix. 512 threads → 8 per thread.

        // Let me just do the straightforward thing:
        // Thread (lane, warpId) loads:
        //   A[(ts+lane)*N + ts+warpId + 0..7] = 8 consecutive half values
        //   B[(ts+lane)*N + ts+warpId + 0..7] = 8 consecutive half values
        // Global stride = N (usually large), so 8 consecutive in a row IS coalesced.
        // But lane maps 0-31, and warpId maps 0-15. 32*16 = 512. ✓

        // Hmm but warpId*8 could go up to 15*8 = 120 which exceeds tile width 64.
        // So warpId should go 0..7 for 8 columns, and lane 0..63 for 64 rows.
        // But we only have 512 threads = 16 warps × 32 lanes.
        // 16 warps → warpId 0..15. 32 lanes → lane 0..31.
        // For row-major tiles: we need 64 rows and 64 cols.
        // Thread 0..511 → row = (threadIdx.x % 64), col = threadIdx.x / 64.
        // But threadIdx.x = warpId*32 + lane. So threadIdx.x % 64 = (warpId*32+lane)%64.
        // For warpId=0: lane 0..31 → row 0..31
        // For warpId=1: lane 0..31 → row 32..63
        // threadIdx.x / 64 = warpId*32+lane / 64.
        // For warpId=0: (0*32+lane)/64 = 0 for all lane → col 0
        // For warpId=1: (32+lane)/64 = 0 for lane 0..31 → col 0
        // For warpId=2: (64+lane)/64 = 1 for all lane → col 1
        // That gives: warpId 0,1 → col 0; warpId 2,3 → col 1; etc.
        // That means threads 0-63 (warpId 0,1) all have col 0.
        // That's only 8 columns for 512 threads → each thread handles 8 elements.

        // Let me just do it with explicit thread indexing:
        // threadIdx.x → (r, c) in the 64×64 tile:
        //   r = threadIdx.x % 64
        //   c = threadIdx.x / 64
        // But threadIdx.x goes 0..511. r=0..63, c=0..7.
        // 8 cols × 64 rows = 512 positions = 512 threads. ✓
        // Each thread handles 1 element from A and 1 from B per tile load.
        // We have 2 tiles (A and B) per k-step. But actually, the entire 64×64
        // tile is loaded once per outer tile iteration (numTiles).
        // So each thread loads 2 half values per numTiles iteration.

        // But wait, we need 8 half per thread (4096/512). So each thread needs
        // to load 8 from A and 8 from B. 16 total.
        // If each thread loads 1 element per tile and we have 4 k-steps per tile
        // (since TILE=64 and each k-step processes MMA=16 elements), then:
        // 4 k-steps × 1 element = 4 elements. That's not enough (need 8).

        // OK, let me restructure. The shared memory holds the full 64×64 tile.
        // Each thread (threadIdx.x) handles position (r, c) where:
        //   r = threadIdx.x % 64, c = threadIdx.x / 64
        // Thread loads: sA[r*64 + c] = A[(ts+r)*N + ts+c] (converted to half)
        //               sB[r*64 + c] = B[(ts+r)*N + ts+c] (converted to half)
        // That's 1 element each, 512 threads → 512 of 4096 covered.
        // We need 4096/512 = 8 per thread.

        // Simplest: each thread loads 8 elements.
        // Thread x loads elements at r, c where:
        //   r = (x * 8) % 64, c = (x * 8) / 64
        // Hmm that doesn't work either since x*8 can exceed 4096.

        // Let me use: each thread loads 8 consecutive elements from row-major order
        // Thread x: offset = x * 8
        //   r = offset / 64, c = offset % 64
        //   → A[(ts+r)*N + ts+c] for c, c+1, ..., c+7 (wrapping)

        // But 64 is not divisible by 8 for the wrapping...
        // Let me just load 8 elements in a row:
        //   Thread x: row = (x % 64), start_col = (x / 64) * 8
        //   loads: A[(ts+row)*N + ts+start_col .. ts+start_col+7]
        // row ∈ [0,63], start_col ∈ {0,8,16,...,56} for x/64 ∈ {0,1,...,7}
        // Each thread loads 8 elements → 512*8=4096. ✓
        // Col start goes 0,8,...,56 → 8 per row. 8 rows per warp. 2 warps per tile row.
        // Total: 4 tile rows × 8 rows × 32 threads = 1024... that's wrong.

        // I'm overcomplicating this. Let me just use a simple mapping:
        // Each thread (id=0..511) loads 8 consecutive half values from the
        // 64×64 tile in row-major order.
        // element_index = id * 8 + k, for k = 0..7
        // tile_row = element_index / 64, tile_col = element_index % 64
        // Global: A[(ts + tile_row) * N + ts + tile_col]

        // For coalescing: consecutive thread IDs (same warp) load consecutive elements.
        // Thread id: warpId*32+lane, element_start = (warpId*32+lane)*8
        // For lane=0,1,...,31: element_start = 0,8,16,...,248 (in row-major of tile)
        // tile_row for lane=0: 0/64=0, tile_col=0%64=0
        // tile_row for lane=4: 32/64=0, tile_col=32%64=32
        // tile_row for lane=7: 56/64=0, tile_col=56%64=56
        // tile_row for lane=8: 64/64=1, tile_col=0%64=0
        // So threads 0-7 cover tile rows 0-0, then thread 8 covers row 1.
        // Consecutive elements 0-7 all in row 0 → coalesced global load from row 0. ✓
        // Consecutive elements 8-15: thread 1 loads elements 8-15. All in row 0.
        // Actually, consecutive THREADS access consecutive ELEMENTS in tile row-major order,
        // which is consecutive in global memory → coalesced! ✓

        // So the mapping is:
        //   Thread x, element k (0..7):
        //     elem = x*8 + k
        //     r = elem / 64
        //     c = elem % 64
        //     sA[r*64 + c] = __float2half(dA[(ts+r)*N + ts+c])

        // But we need to also handle boundary conditions for non-tile-aligned N.

        for (int e = 0; e < 8; ++e) {
            int elem = threadIdx.x * 8 + e;
            if (elem < TILE * TILE) {
                int r = elem / TILE;
                int c = elem % TILE;
                int gr = ts + r;
                int gc = ts + c;
                if (gr < N && gc < N) {
                    sA[r * TILE + c] = __float2half(dA[gr * N + gc]);
                    sB[r * TILE + c] = __float2half(dB[gr * N + gc]);
                }
            }
        }

        __syncthreads();

        // -----------------------------------------------------------
        // 2) Load wmma fragments from shared memory
        // -----------------------------------------------------------
        // 4 wmma steps (k-index 0..3)
        // For warp group (wgRow, wgCol):
        //   A fragments: rows [wgRow*MMA .. +15], cols [w*MMA .. +15] for w=0..3
        //   B fragments: rows [w*MMA .. +15], cols [wgCol*MMA .. +15] for w=0..3
        matA a_frag[WGRP];
        matB b_frag[WGRP];
        #pragma unroll
        for (int w = 0; w < WGRP; ++w) {
            wmma::load_matrix_sync(a_frag[w], sA + (wgRow * MMA + w * MMA) * TILE + MMA * 0, TILE, wmma::mem_row_major);
            wmma::load_matrix_sync(b_frag[w], sB + (w * MMA) * TILE + wgCol * MMA, TILE, wmma::mem_col_major);
        }

        // -----------------------------------------------------------
        // 3) wmma multiply-accumulate
        // -----------------------------------------------------------
        #pragma unroll
        for (int w = 0; w < WGRP; ++w) {
            #pragma unroll
            for (int j = 0; j < WGRP; ++j) {
                wmma::mma_sync(accum[j], a_frag[w], b_frag[j], accum[j]);
            }
        }

        __syncthreads();
    }

    // -----------------------------------------------------------
    // 4) Store 4 accumulators to global memory (FP32 output)
    // -----------------------------------------------------------
    #pragma unroll
    for (int j = 0; j < WGRP; ++j) {
        wmma::store_matrix_sync(dC + gRow * N + (gCol + j * MMA),
                                accum[j], N, wmma::mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(512);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block, SBYTES>>>(dA, dB, dC, N);
}

